from pathlib import Path
import shutil,html,os
ROOT=Path(__file__).resolve().parents[1]; SOURCE=ROOT/'artifacts'/os.environ.get('NAQLA_FULL_ACCEPTANCE','release-acceptance-10.0.13'); DEST=ROOT/'preview/context-editors'; DEST.mkdir(exist_ok=True)
views=[('ocr','OCR · النص'),('background','عزل الخلفية'),('subtitle','نص الكلام'),('privacy','الخصوصية'),('frames','إطارات الفيديو'),('trim','قص زمني'),('normalize','تطبيع الصوت'),('silence','قص الصمت'),('channels','القنوات'),('archive','الأرشفة')]
for key,title in views: shutil.copyfile(SOURCE/f'native-{key}-editor.png',DEST/f'{key}.png')
for n in (1,2): shutil.copyfile(SOURCE/f'native-tools-page-{n}.png',DEST/f'tools-{n}.png')
buttons=''.join(f'<button data-key="{key}">{html.escape(title)}</button>' for key,title in views)
page='''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Naqla · مراجعة المحررات</title>
<style>*{box-sizing:border-box}body{margin:0;background:#121820;color:#f5f0e6;font:14px/1.8 Segoe UI,Tahoma,sans-serif}main{max-width:1020px;margin:auto;padding:24px}h1{color:#ffc35a;font-size:26px}p{color:#b9c5ce}nav{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0}button{font:inherit;color:#f5f0e6;background:#1c2530;border:1px solid #415266;padding:7px 12px;cursor:pointer}button[aria-selected=true]{background:#ffc35a;color:#121820}button:focus-visible{outline:2px solid #ffc35a;outline-offset:3px}.stage{padding:16px;background:#0b1119;border:1px solid #344454;display:flex;justify-content:center}#editor{max-width:100%;height:auto;width:554px;align-self:flex-start}.wheels{display:flex;flex-wrap:wrap;justify-content:center;gap:16px}.wheels img{width:260px;height:306px}a{color:#ffc35a}</style>
<main><h1>نقلة · مراجعة المحررات السياقية</h1><p>صور من تخطيط WPF الفعلي خارج الشاشة بحجم 554 × 580 DIP؛ ليست تسجيل سحب أو اختبار نقرات. المعالجة الخلفية حقيقية ومختبرة بصورة منفصلة. المعاينة الفارغة في OCR/النموذج تتطلب إنشاء معاينة فعلية قبل تفعيل الحفظ.</p><nav>BUTTONS</nav><div class="stage"><img id="editor" src="context-editors/ocr.png" alt="OCR"></div><p>صفحات الأدوات المعتمدة، بالحجم الأصلي: ستة قطاعات كحد أقصى ونقاط في المركز. حُفظ شكل العجلة والكبسولة والأزرار.</p><div class="wheels"><img src="context-editors/tools-1.png" alt="صفحة الأدوات الأولى"><img src="context-editors/tools-2.png" alt="الثانية"></div><p><a href="pdf-toolkit.html">مراجعة محرر PDF</a> · <a href="index.html">التصميم المنفصل للعجلة</a> · <a href="../docs/MANUAL-WINDOWS-TESTS.md">اختبارات Windows اليدوية</a></p></main>
<script>const img=document.querySelector('#editor');for(const button of document.querySelectorAll('button')){button.setAttribute('aria-selected',button.dataset.key==='ocr');button.onclick=()=>{for(const other of document.querySelectorAll('button'))other.setAttribute('aria-selected',other===button);img.src='context-editors/'+button.dataset.key+'.png';img.alt=button.textContent;};}</script></html>'''.replace('BUTTONS',buttons)
(ROOT/'preview/context-editors.html').write_text(page,encoding='utf-8')
print('Created contextual editor review gallery.')
